import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);

  // Plane dimensions maintain 512:320 aspect ratio
  const height = 0.6;
  const width = height * (512 / 320);

  // Create geometry and material
  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(textureAsset),
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transform from config
  if (config.scenePosition) {
    mesh.position.set(config.scenePosition.x, config.scenePosition.y, config.scenePosition.z);
  } else {
    mesh.position.set(0, -0.3, 0);
  }

  if (config.sceneRotation) {
    mesh.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }

  if (config.sceneScale) {
    mesh.scale.set(config.sceneScale.x, config.sceneScale.y, config.sceneScale.z);
  }

  group.add(mesh);

  // Initialize handlers and cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
    gsap.killTweensOf(group);
    gsap.killTweensOf(mesh);
  };

  return group;
}
